-- =========================================================
-- Ruta Doce de Octubre: tablas, permisos y datos iniciales
-- Pegar todo en Supabase → SQL Editor → Run. Se puede correr otra vez sin problema.
-- =========================================================

-- 1. TABLAS ------------------------------------------------
create table if not exists perfiles (
  id uuid primary key references auth.users on delete cascade,
  nombre text not null default '',
  rol text not null default 'turista' check (rol in ('turista','admin')),
  creado_en timestamptz default now()
);

create table if not exists lugares (
  id text primary key,
  titulo text not null,
  subtitulo text,
  relato text,
  categoria text not null,
  tipo text,
  imagenes text[] default '{}',
  imagen_alt text,
  narrador_audio text,
  segundos_audio int default 0,
  codigo_qr text unique,
  lat double precision not null,
  lng double precision not null,
  direccion text,
  etiquetas text[] default '{}'
);

create table if not exists recorridos (
  id text primary key,
  titulo text not null,
  descripcion_corta text,
  descripcion text,
  cita text,
  categoria text not null,
  distancia_km numeric,
  duracion_min int,
  dificultad text,
  sustantivo_paradas text,
  etiqueta text,
  destacado boolean default false,
  portada text,
  portada_alt text,
  tiene_audioguia boolean default true,
  curador text,
  rol_curador text,
  caracteristica jsonb,
  creado_en timestamptz default now()
);
-- Por si ya habías creado la tabla con la versión anterior de este archivo
alter table recorridos add column if not exists caracteristica jsonb;

create table if not exists recorrido_lugares (
  recorrido_id text references recorridos on delete cascade,
  lugar_id text references lugares on delete cascade,
  orden int not null,
  primary key (recorrido_id, lugar_id)
);

create table if not exists resenas (
  id uuid primary key default gen_random_uuid(),
  usuario_id uuid references auth.users on delete cascade,
  autor text,
  tipo text not null check (tipo in ('tour','point')),
  objetivo_id text not null,
  estrellas int not null check (estrellas between 1 and 5),
  comentario text,
  fecha timestamptz default now()
);

create table if not exists visitas (
  id uuid primary key default gen_random_uuid(),
  usuario_id uuid references auth.users on delete cascade,
  recorrido_id text,
  lugar_id text,
  fecha timestamptz default now()
);

create table if not exists favoritos (
  usuario_id uuid references auth.users on delete cascade,
  recorrido_id text references recorridos on delete cascade,
  primary key (usuario_id, recorrido_id)
);

-- Crea el perfil automáticamente cuando alguien se registra
create or replace function crear_perfil() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into perfiles (id, nombre) values (new.id, coalesce(new.raw_user_meta_data->>'nombre', ''));
  return new;
end; $$;
drop trigger if exists al_registrarse on auth.users;
create trigger al_registrarse after insert on auth.users
  for each row execute function crear_perfil();

-- 2. PERMISOS ----------------------------------------------
create or replace function es_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from perfiles where id = auth.uid() and rol = 'admin');
$$;

alter table perfiles enable row level security;
alter table lugares enable row level security;
alter table recorridos enable row level security;
alter table recorrido_lugares enable row level security;
alter table resenas enable row level security;
alter table visitas enable row level security;
alter table favoritos enable row level security;

drop policy if exists "ver lugares" on lugares;
create policy "ver lugares" on lugares for select using (true);
drop policy if exists "admin edita lugares" on lugares;
create policy "admin edita lugares" on lugares for all using (es_admin()) with check (es_admin());
drop policy if exists "ver recorridos" on recorridos;
create policy "ver recorridos" on recorridos for select using (true);
drop policy if exists "admin edita recorridos" on recorridos;
create policy "admin edita recorridos" on recorridos for all using (es_admin()) with check (es_admin());
drop policy if exists "ver orden" on recorrido_lugares;
create policy "ver orden" on recorrido_lugares for select using (true);
drop policy if exists "admin edita orden" on recorrido_lugares;
create policy "admin edita orden" on recorrido_lugares for all using (es_admin()) with check (es_admin());
drop policy if exists "ver resenas" on resenas;
create policy "ver resenas" on resenas for select using (true);
drop policy if exists "crear mi resena" on resenas;
create policy "crear mi resena" on resenas for insert with check (usuario_id = auth.uid());
drop policy if exists "borrar mi resena" on resenas;
create policy "borrar mi resena" on resenas for delete using (usuario_id = auth.uid() or es_admin());
drop policy if exists "ver mis visitas" on visitas;
create policy "ver mis visitas" on visitas for select using (usuario_id = auth.uid() or es_admin());
drop policy if exists "sellar mi visita" on visitas;
create policy "sellar mi visita" on visitas for insert with check (usuario_id = auth.uid());
drop policy if exists "mis favoritos" on favoritos;
create policy "mis favoritos" on favoritos for all using (usuario_id = auth.uid()) with check (usuario_id = auth.uid());
drop policy if exists "ver mi perfil" on perfiles;
create policy "ver mi perfil" on perfiles for select using (id = auth.uid() or es_admin());
-- Cada uno edita su nombre, pero no puede cambiarse el rol a sí mismo
create or replace function mi_rol() returns text
language sql stable security definer set search_path = public as $$
  select rol from perfiles where id = auth.uid();
$$;
drop policy if exists "editar mi perfil" on perfiles;
create policy "editar mi perfil" on perfiles for update using (id = auth.uid()) with check (id = auth.uid() and rol = mi_rol());

-- 3. DATOS: 22 LUGARES -------------------------------------
