insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('parque-pedregal', 'Parque de Pedregal', 'Parque barrial sobre la Carrera 74.', 'Espacio público central del barrio Pedregal, rodeado de comercio y ventas de comida. Los fines de semana es lugar de encuentro de familias. Desde aquí se camina en pocos minutos hacia la estación SENA del Metrocable y hacia el Parque Biblioteca Gabriel García Márquez.', 'historico', 'Parque barrial', array['https://lh3.googleusercontent.com/aida-public/AB6AXuCjpUgBaQyypwNnwLItZlYCkolxBIVHxs4jyyOeNPmJ7IFTeTGqMCZjFylc55YtlKr4Pvxkwmz_oUWcBxJQD0ljqmKBfb7fQsZ168WMHQggiyMMhSNEpTIC9-spMEzkr5bPBD-xuo-kWHqT5bHEEHU6bTDmyDE72IwMFkRx3Rkx7exZQ1Cuykzjxl7V259kzPB0rMEA9GoS8Pu8X4wEQ-ihYMKCduHDhZn92id5naqaLxVhOaA8F6ah', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAFiBkfz77iDygsyx09lHJxtziPBsDiUU7b_gonVeb0WxUZOUgDAfaMy21y2efkzyBGZWy4IS2eAPsZiL7_xZJzdJd9u1Mb6tUXbtuHN4d0oVe1KivARfS0Ex4Dq0Cm_hMNxrr-wLN0gE0b-iiv0gx3295_m-OBS699oKgUO-AwmIXILgJY8N3_RSTr0nCbZFEUwcTgpn0DxHL-Irj6tgbgx9Tujwph66VOxz6I8ZehRanXv4Aciw9M', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDIWEW91s86ZtCO6mqjokU4SaseGxoiuUryctQ-pYvHNbXvfRxqotKuvbz0ECp6AedyPwGJLtCnSC59ZCvMuNybrA_kkVCanzc8tIMPoNS_YmdVyq2wPtDOlrJ6k-3MQtQ4zTBlbTAUKg9MjPbKIBtAenBD5N_hfKOk0HlgsNLE1zCrUzPHqCEWt2l9A6TGx9j7vM3m69GRZiFnU_exej_-RWvnPG3VIr0Hvk_51zkkn9_37T_0Fctf']::text[], 'Imagen ilustrativa (no es una fotografía de el Parque de Pedregal)', 'Audioguía Ruta Doce de Octubre', 110, 'QR-DOCE-03', 6.3025296, -75.5718425, 'Carrera 74, Pedregal', array['Espacio público', 'Pedregal', 'Encuentro']::text[]) on conflict (id) do nothing;
insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('parroquia-santa-maria-carmen', 'Parroquia Santa María del Carmen', 'Templo del barrio Doce de Octubre N.º 1.', 'El barrio Doce de Octubre fue construido por el Instituto de Crédito Territorial entre 1970 y 1976, en cuatro etapas, y dio su nombre a toda la comuna. Esta parroquia, en el sector de Doce de Octubre N.º 1, está a pocas cuadras de la Carrera 80, el principal corredor vial y comercial de la comuna.', 'historico', 'Templo parroquial', array['https://lh3.googleusercontent.com/aida-public/AB6AXuCexTWnVFzPxo-GxnbgeAxmzRxzrdD8EnQo_51zE-m8NAwpSba0wU1qn27FfKrJ5CzgPJsHv3o5PwsDxuE2go9_08uqahoMMy66WlDMFZl37PDEqSv4UmeqahBLfGe2AXkI_p2p0GhHaMBfNUZr8ocZWvZmP9RBbyhimR9_JcwU3v_MDu7oJSNxcD1aJ07LEGO8jjtlnxdzu-B4bXzsRy40u1LTjmUIJiODbwENHsF_vTeUowQ5yB9J', 'https://lh3.googleusercontent.com/aida-public/AB6AXuCjpUgBaQyypwNnwLItZlYCkolxBIVHxs4jyyOeNPmJ7IFTeTGqMCZjFylc55YtlKr4Pvxkwmz_oUWcBxJQD0ljqmKBfb7fQsZ168WMHQggiyMMhSNEpTIC9-spMEzkr5bPBD-xuo-kWHqT5bHEEHU6bTDmyDE72IwMFkRx3Rkx7exZQ1Cuykzjxl7V259kzPB0rMEA9GoS8Pu8X4wEQ-ihYMKCduHDhZn92id5naqaLxVhOaA8F6ah', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAFiBkfz77iDygsyx09lHJxtziPBsDiUU7b_gonVeb0WxUZOUgDAfaMy21y2efkzyBGZWy4IS2eAPsZiL7_xZJzdJd9u1Mb6tUXbtuHN4d0oVe1KivARfS0Ex4Dq0Cm_hMNxrr-wLN0gE0b-iiv0gx3295_m-OBS699oKgUO-AwmIXILgJY8N3_RSTr0nCbZFEUwcTgpn0DxHL-Irj6tgbgx9Tujwph66VOxz6I8ZehRanXv4Aciw9M']::text[], 'Imagen ilustrativa (no es una fotografía de la Parroquia Santa María del Carmen)', 'Audioguía Ruta Doce de Octubre', 130, 'QR-DOCE-04', 6.303514, -75.5784829, 'Calle 102B # 82-40, Doce de Octubre N.º 1', array['Doce de Octubre', 'Instituto de Crédito Territorial', 'Carrera 80']::text[]) on conflict (id) do nothing;
