insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('estacion-doce-de-octubre', 'Estación Doce de Octubre (Metrocable Línea P)', 'Estación intermedia del Metrocable Picacho.', 'La Línea P (Metrocable Picacho) empezó a operar en junio de 2021. Tiene 2,7 km y cuatro estaciones: Acevedo, SENA, Doce de Octubre y El Progreso, y conecta la parte alta de la comuna con la Línea A del Metro en Acevedo. Esta estación está junto al Parque Biblioteca Gabriel García Márquez.', 'miradores', 'Estación de Metrocable', array['https://lh3.googleusercontent.com/aida-public/AB6AXuDm8juEbgGtiLRulubKxDe_5BCaA2LGGjxhdA7VKk59ukytdpZ4O8wufY1ADTpUSQgVwl88kE7yd3lk_YWKc_0hKg53RnRtNcXRcS21nxQSkk-Nlp6JKtzMpL2SyilOqyAo_ddFyBPw24cpfhLJOTl4jABaqZsaDBohZVfBVsxxnB30Mg9135MHGEJwU5tV1GsKoDY4rl7mKT0U6x_R5dE_1xkheiXyzMLwveR7q--B8UQ1nR4EULpl', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAFiBkfz77iDygsyx09lHJxtziPBsDiUU7b_gonVeb0WxUZOUgDAfaMy21y2efkzyBGZWy4IS2eAPsZiL7_xZJzdJd9u1Mb6tUXbtuHN4d0oVe1KivARfS0Ex4Dq0Cm_hMNxrr-wLN0gE0b-iiv0gx3295_m-OBS699oKgUO-AwmIXILgJY8N3_RSTr0nCbZFEUwcTgpn0DxHL-Irj6tgbgx9Tujwph66VOxz6I8ZehRanXv4Aciw9M', 'https://lh3.googleusercontent.com/aida-public/AB6AXuBlLbSSaQRiuRY6HwuMTZFyM8cM7Im9vzousbjKurUJQXhjki_q7e6ozO9QEtb9n4yH0UIRIZ7ayAStLW9g1Bz__PYXaT6BlqJU_49G0eIdLN6kzodM6-QZqHLrjQvaUAEclE0ULpce3zdbMyhTOn3DwHgY_VRfV2zpqa8R8M8tWtNycryIEddjgSgbmfvdxHe967Fcoijk2gGvjJjPjqxqRpEktwXZVIjsq_i_CEP4SmXDdzaST2dc']::text[], 'Imagen ilustrativa (no es una fotografía de la estación Doce de Octubre del Metrocable)', 'Audioguía Ruta Doce de Octubre', 120, 'QR-DOCE-13', 6.3042013, -75.5760776, 'Calle 105 # 80-18, Santander', array['Metrocable', 'Línea P', 'Transporte']::text[]) on conflict (id) do nothing;
insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('estacion-el-progreso', 'Estación El Progreso (Metrocable Línea P)', 'Última estación de la Línea P, en lo alto de la comuna.', 'Estación final de la Línea P, en el barrio El Progreso N.º 2. Desde la estación hay vista panorámica de Medellín y desde aquí se puede subir a pie hacia el Cerro El Picacho. Un paseo urbano conecta la estación con el barrio.', 'miradores', 'Estación y mirador', array['https://lh3.googleusercontent.com/aida-public/AB6AXuDm8juEbgGtiLRulubKxDe_5BCaA2LGGjxhdA7VKk59ukytdpZ4O8wufY1ADTpUSQgVwl88kE7yd3lk_YWKc_0hKg53RnRtNcXRcS21nxQSkk-Nlp6JKtzMpL2SyilOqyAo_ddFyBPw24cpfhLJOTl4jABaqZsaDBohZVfBVsxxnB30Mg9135MHGEJwU5tV1GsKoDY4rl7mKT0U6x_R5dE_1xkheiXyzMLwveR7q--B8UQ1nR4EULpl', 'https://lh3.googleusercontent.com/aida-public/AB6AXuBlLbSSaQRiuRY6HwuMTZFyM8cM7Im9vzousbjKurUJQXhjki_q7e6ozO9QEtb9n4yH0UIRIZ7ayAStLW9g1Bz__PYXaT6BlqJU_49G0eIdLN6kzodM6-QZqHLrjQvaUAEclE0ULpce3zdbMyhTOn3DwHgY_VRfV2zpqa8R8M8tWtNycryIEddjgSgbmfvdxHe967Fcoijk2gGvjJjPjqxqRpEktwXZVIjsq_i_CEP4SmXDdzaST2dc', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAFiBkfz77iDygsyx09lHJxtziPBsDiUU7b_gonVeb0WxUZOUgDAfaMy21y2efkzyBGZWy4IS2eAPsZiL7_xZJzdJd9u1Mb6tUXbtuHN4d0oVe1KivARfS0Ex4Dq0Cm_hMNxrr-wLN0gE0b-iiv0gx3295_m-OBS699oKgUO-AwmIXILgJY8N3_RSTr0nCbZFEUwcTgpn0DxHL-Irj6tgbgx9Tujwph66VOxz6I8ZehRanXv4Aciw9M']::text[], 'Imagen ilustrativa (no es una fotografía de la estación El Progreso del Metrocable)', 'Audioguía Ruta Doce de Octubre', 120, 'QR-DOCE-14', 6.3059313, -75.5821909, 'Barrio El Progreso N.º 2', array['Metrocable', 'Vista panorámica', 'El Progreso']::text[]) on conflict (id) do nothing;
insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('parroquia-santa-teresa-jesus', 'Parroquia Santa Teresa de Jesús', 'Templo del barrio El Progreso, camino al cerro.', 'Parroquia del barrio El Progreso, en la parte alta de la comuna. Está en el camino entre la estación El Progreso del Metrocable y los senderos que suben al Cerro El Picacho.', 'miradores', 'Templo parroquial', array['https://lh3.googleusercontent.com/aida-public/AB6AXuCexTWnVFzPxo-GxnbgeAxmzRxzrdD8EnQo_51zE-m8NAwpSba0wU1qn27FfKrJ5CzgPJsHv3o5PwsDxuE2go9_08uqahoMMy66WlDMFZl37PDEqSv4UmeqahBLfGe2AXkI_p2p0GhHaMBfNUZr8ocZWvZmP9RBbyhimR9_JcwU3v_MDu7oJSNxcD1aJ07LEGO8jjtlnxdzu-B4bXzsRy40u1LTjmUIJiODbwENHsF_vTeUowQ5yB9J', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAFiBkfz77iDygsyx09lHJxtziPBsDiUU7b_gonVeb0WxUZOUgDAfaMy21y2efkzyBGZWy4IS2eAPsZiL7_xZJzdJd9u1Mb6tUXbtuHN4d0oVe1KivARfS0Ex4Dq0Cm_hMNxrr-wLN0gE0b-iiv0gx3295_m-OBS699oKgUO-AwmIXILgJY8N3_RSTr0nCbZFEUwcTgpn0DxHL-Irj6tgbgx9Tujwph66VOxz6I8ZehRanXv4Aciw9M', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDm8juEbgGtiLRulubKxDe_5BCaA2LGGjxhdA7VKk59ukytdpZ4O8wufY1ADTpUSQgVwl88kE7yd3lk_YWKc_0hKg53RnRtNcXRcS21nxQSkk-Nlp6JKtzMpL2SyilOqyAo_ddFyBPw24cpfhLJOTl4jABaqZsaDBohZVfBVsxxnB30Mg9135MHGEJwU5tV1GsKoDY4rl7mKT0U6x_R5dE_1xkheiXyzMLwveR7q--B8UQ1nR4EULpl']::text[], 'Imagen ilustrativa (no es una fotografía de la Parroquia Santa Teresa de Jesús)', 'Audioguía Ruta Doce de Octubre', 100, 'QR-DOCE-15', 6.3070931, -75.5825888, 'Carrera 84A # 104B-58, El Progreso', array['El Progreso', 'Camino al Picacho', 'Comunidad']::text[]) on conflict (id) do nothing;
insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('cristo-del-picacho', 'Cristo del Picacho', 'Monumento en la cima del cerro tutelar.', 'En 1936 Monseñor Félix Henao Botero propuso instalar en la cima del Picacho una imagen de Cristo de 2,5 metros. La escultura, con los brazos abiertos hacia el Valle de Aburrá, es hoy lugar de peregrinación y uno de los íconos del noroccidente de Medellín. Se llega subiendo escaleras desde la vía.', 'miradores', 'Monumento', array['https://lh3.googleusercontent.com/aida-public/AB6AXuCexTWnVFzPxo-GxnbgeAxmzRxzrdD8EnQo_51zE-m8NAwpSba0wU1qn27FfKrJ5CzgPJsHv3o5PwsDxuE2go9_08uqahoMMy66WlDMFZl37PDEqSv4UmeqahBLfGe2AXkI_p2p0GhHaMBfNUZr8ocZWvZmP9RBbyhimR9_JcwU3v_MDu7oJSNxcD1aJ07LEGO8jjtlnxdzu-B4bXzsRy40u1LTjmUIJiODbwENHsF_vTeUowQ5yB9J', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDm8juEbgGtiLRulubKxDe_5BCaA2LGGjxhdA7VKk59ukytdpZ4O8wufY1ADTpUSQgVwl88kE7yd3lk_YWKc_0hKg53RnRtNcXRcS21nxQSkk-Nlp6JKtzMpL2SyilOqyAo_ddFyBPw24cpfhLJOTl4jABaqZsaDBohZVfBVsxxnB30Mg9135MHGEJwU5tV1GsKoDY4rl7mKT0U6x_R5dE_1xkheiXyzMLwveR7q--B8UQ1nR4EULpl', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAFiBkfz77iDygsyx09lHJxtziPBsDiUU7b_gonVeb0WxUZOUgDAfaMy21y2efkzyBGZWy4IS2eAPsZiL7_xZJzdJd9u1Mb6tUXbtuHN4d0oVe1KivARfS0Ex4Dq0Cm_hMNxrr-wLN0gE0b-iiv0gx3295_m-OBS699oKgUO-AwmIXILgJY8N3_RSTr0nCbZFEUwcTgpn0DxHL-Irj6tgbgx9Tujwph66VOxz6I8ZehRanXv4Aciw9M']::text[], 'Imagen ilustrativa (no es una fotografía de el Cristo del Picacho)', 'Audioguía Ruta Doce de Octubre', 150, 'QR-DOCE-16', 6.3040685, -75.5883827, 'Cerro El Picacho, sector Picacho', array['Cerro tutelar', 'Patrimonio', 'Peregrinación']::text[]) on conflict (id) do nothing;
insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('mirador-cerro-el-picacho', 'Mirador Cerro El Picacho', 'Ecoparque y mirador de uno de los siete cerros tutelares.', 'El Cerro El Picacho es uno de los siete cerros tutelares de Medellín y funciona como ecoparque mirador, con una de las mejores vistas del Valle de Aburrá. Según la Alcaldía, allí se han reportado 46 especies de aves y 59 especies de árboles, 33 de ellas nativas del valle. Uno de sus senderos sube desde el barrio Picachito siguiendo la quebrada La Minita.', 'miradores', 'Ecoparque mirador', array['https://lh3.googleusercontent.com/aida-public/AB6AXuDm8juEbgGtiLRulubKxDe_5BCaA2LGGjxhdA7VKk59ukytdpZ4O8wufY1ADTpUSQgVwl88kE7yd3lk_YWKc_0hKg53RnRtNcXRcS21nxQSkk-Nlp6JKtzMpL2SyilOqyAo_ddFyBPw24cpfhLJOTl4jABaqZsaDBohZVfBVsxxnB30Mg9135MHGEJwU5tV1GsKoDY4rl7mKT0U6x_R5dE_1xkheiXyzMLwveR7q--B8UQ1nR4EULpl', 'https://lh3.googleusercontent.com/aida-public/AB6AXuBlLbSSaQRiuRY6HwuMTZFyM8cM7Im9vzousbjKurUJQXhjki_q7e6ozO9QEtb9n4yH0UIRIZ7ayAStLW9g1Bz__PYXaT6BlqJU_49G0eIdLN6kzodM6-QZqHLrjQvaUAEclE0ULpce3zdbMyhTOn3DwHgY_VRfV2zpqa8R8M8tWtNycryIEddjgSgbmfvdxHe967Fcoijk2gGvjJjPjqxqRpEktwXZVIjsq_i_CEP4SmXDdzaST2dc', 'https://lh3.googleusercontent.com/aida-public/AB6AXuCexTWnVFzPxo-GxnbgeAxmzRxzrdD8EnQo_51zE-m8NAwpSba0wU1qn27FfKrJ5CzgPJsHv3o5PwsDxuE2go9_08uqahoMMy66WlDMFZl37PDEqSv4UmeqahBLfGe2AXkI_p2p0GhHaMBfNUZr8ocZWvZmP9RBbyhimR9_JcwU3v_MDu7oJSNxcD1aJ07LEGO8jjtlnxdzu-B4bXzsRy40u1LTjmUIJiODbwENHsF_vTeUowQ5yB9J']::text[], 'Imagen ilustrativa (no es una fotografía de el mirador del Cerro El Picacho)', 'Audioguía Ruta Doce de Octubre', 170, 'QR-DOCE-17', 6.3039645, -75.5898441, 'Cerro El Picacho, sector Picachito', array['Cerro tutelar', 'Aves', 'Senderismo']::text[]) on conflict (id) do nothing;
insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('parque-biblioteca-ggm', 'Parque Biblioteca Gabriel García Márquez', 'El «parque periscopio» del Doce de Octubre.', 'Surgió de un concurso de arquitectura de 2009 y abrió al público el 19 de agosto de 2013. Tiene cinco niveles con sala infantil, biblioteca para adultos, préstamo, espacio para teatro y salas de música, danza y exposiciones. Su periscopio ofrece una vista de 360° sobre la comuna.', 'musica', 'Parque biblioteca', array['https://lh3.googleusercontent.com/aida-public/AB6AXuDIWEW91s86ZtCO6mqjokU4SaseGxoiuUryctQ-pYvHNbXvfRxqotKuvbz0ECp6AedyPwGJLtCnSC59ZCvMuNybrA_kkVCanzc8tIMPoNS_YmdVyq2wPtDOlrJ6k-3MQtQ4zTBlbTAUKg9MjPbKIBtAenBD5N_hfKOk0HlgsNLE1zCrUzPHqCEWt2l9A6TGx9j7vM3m69GRZiFnU_exej_-RWvnPG3VIr0Hvk_51zkkn9_37T_0Fctf', 'https://lh3.googleusercontent.com/aida-public/AB6AXuCVYQsNrSr5iRCy2IZmf0rDyA-5K30OrE-_WXPBuvLAA5MblIm0H9WwUI1zF8v2B6ubHT9dDzsbKCsgaQimr676-Dia0uxhkC1v3GnSQIXLcSe8_V1QpU5hbFlTnEhyYFC8YpFD_2UCHKoyQUzQ-42G7yNsrTyUgW0VnSmYnOEtsnUBWVpyJnXIRpzUAs4rvm3EWGf37RoJUnfmHscvWOudaoDFEOzMrY-aSzmnGxMhGhEwkppOlj3z', 'https://lh3.googleusercontent.com/aida-public/AB6AXuBsQNeJXIGahul0h-aLToW20PRUgY765_SrDZLxsP3OWQ9meQ0H67xfnmBjm9U7QfTK2-PqpJ1Dex5lYZkCdyX-Z1NR1ZygQgLyfRILwFw3i2cX9ZUGKD1e3i2LvgygAxIseOynSrhI3W4kOcVxIbOQujW4sQ2vPIW_gO5LbzzEOwLRcqLlh6q_BtBY9GhNhXXPQ8pT5Z3pNvATyeuGtOJvGe2y7JEQLmBXNY0Lnso9FMa_QlQOXtQ9']::text[], 'Imagen ilustrativa (no es una fotografía de el Parque Biblioteca Gabriel García Márquez)', 'Audioguía Ruta Doce de Octubre', 180, 'QR-DOCE-18', 6.3040491, -75.5777583, 'Carrera 80 # 104-04, Santander', array['Biblioteca', 'Arquitectura', 'Cultura']::text[]) on conflict (id) do nothing;
