insert into lugares (id, titulo, subtitulo, relato, categoria, tipo, imagenes, imagen_alt, narrador_audio, segundos_audio, codigo_qr, lat, lng, direccion, etiquetas) values ('cic-comunas-5-6', 'Centro de Integración Comunitaria (CIC) Comunas 5 y 6', 'Grupos culturales, biblioteca y escuela de danza.', 'Asociación comunitaria que reúne a vecinos de las comunas 5 y 6. Acoge grupos culturales, una biblioteca, grupos de niñez, juventud y adultos mayores, y una escuela de danza.', 'musica', 'Centro comunitario', array['https://lh3.googleusercontent.com/aida-public/AB6AXuBsQNeJXIGahul0h-aLToW20PRUgY765_SrDZLxsP3OWQ9meQ0H67xfnmBjm9U7QfTK2-PqpJ1Dex5lYZkCdyX-Z1NR1ZygQgLyfRILwFw3i2cX9ZUGKD1e3i2LvgygAxIseOynSrhI3W4kOcVxIbOQujW4sQ2vPIW_gO5LbzzEOwLRcqLlh6q_BtBY9GhNhXXPQ8pT5Z3pNvATyeuGtOJvGe2y7JEQLmBXNY0Lnso9FMa_QlQOXtQ9', 'https://lh3.googleusercontent.com/aida-public/AB6AXuCVYQsNrSr5iRCy2IZmf0rDyA-5K30OrE-_WXPBuvLAA5MblIm0H9WwUI1zF8v2B6ubHT9dDzsbKCsgaQimr676-Dia0uxhkC1v3GnSQIXLcSe8_V1QpU5hbFlTnEhyYFC8YpFD_2UCHKoyQUzQ-42G7yNsrTyUgW0VnSmYnOEtsnUBWVpyJnXIRpzUAs4rvm3EWGf37RoJUnfmHscvWOudaoDFEOzMrY-aSzmnGxMhGhEwkppOlj3z', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDIWEW91s86ZtCO6mqjokU4SaseGxoiuUryctQ-pYvHNbXvfRxqotKuvbz0ECp6AedyPwGJLtCnSC59ZCvMuNybrA_kkVCanzc8tIMPoNS_YmdVyq2wPtDOlrJ6k-3MQtQ4zTBlbTAUKg9MjPbKIBtAenBD5N_hfKOk0HlgsNLE1zCrUzPHqCEWt2l9A6TGx9j7vM3m69GRZiFnU_exej_-RWvnPG3VIr0Hvk_51zkkn9_37T_0Fctf']::text[], 'Imagen ilustrativa (no es una fotografía de el Centro de Integración Comunitaria)', 'Audioguía Ruta Doce de Octubre', 100, 'QR-DOCE-21', 6.2933791, -75.5759184, 'Carrera 73 # 96-105', array['Danza', 'Comunidad', 'Biblioteca']::text[]) on conflict (id) do nothing;

