insert into recorridos (id, titulo, descripcion_corta, descripcion, cita, categoria, distancia_km, duracion_min, dificultad, sustantivo_paradas, etiqueta, destacado, portada, portada_alt, tiene_audioguia, curador, rol_curador, caracteristica, creado_en) values ('memorias-del-territorio', 'Memorias del Territorio: De Pedregal al Doce', 'Recorrido por Pedregal y Doce de Octubre N.º 1, dos barrios que el Instituto de Crédito Territorial loteó entre 1962 y 1976 y que sus familias construyeron.', 'La Comuna 6 se formó por etapas: la urbanización Santander en 1951, el loteo de Pedregal por el Instituto de Crédito Territorial en 1962, la construcción del barrio Doce de Octubre entre 1970 y 1976 y los asentamientos de El Triunfo desde 1984. Este recorrido pasa por templos, la Casa de la Cultura y el parque de Pedregal para terminar en Doce de Octubre N.º 1, cerca de la Carrera 80.', null, 'historico', 1.7, 60, 'Fácil', 'puntos de interés', 'Ruta insignia', true, 'https://lh3.googleusercontent.com/aida-public/AB6AXuAFiBkfz77iDygsyx09lHJxtziPBsDiUU7b_gonVeb0WxUZOUgDAfaMy21y2efkzyBGZWy4IS2eAPsZiL7_xZJzdJd9u1Mb6tUXbtuHN4d0oVe1KivARfS0Ex4Dq0Cm_hMNxrr-wLN0gE0b-iiv0gx3295_m-OBS699oKgUO-AwmIXILgJY8N3_RSTr0nCbZFEUwcTgpn0DxHL-Irj6tgbgx9Tujwph66VOxz6I8ZehRanXv4Aciw9M', 'Imagen ilustrativa de un barrio de ladera en Medellín', true, 'Equipo Ruta Doce de Octubre', 'Contenido basado en fuentes públicas', '{"icon":"history_edu","label":"Historia de los barrios"}'::jsonb, '2024-03-01T00:00:00.000Z') on conflict (id) do update set caracteristica = excluded.caracteristica;
