insert into recorridos (id, titulo, descripcion_corta, descripcion, cita, categoria, distancia_km, duracion_min, dificultad, sustantivo_paradas, etiqueta, destacado, portada, portada_alt, tiene_audioguia, curador, rol_curador, caracteristica, creado_en) values ('parques-y-encuentro', 'Parques y Encuentro: Deporte y Vida al Aire Libre', 'Parques de barrio, la sede de Comfama Pedregal y la Unidad Deportiva del Doce de Octubre: los espacios donde la comuna se encuentra.', 'Un recorrido de sur a norte por los espacios recreativos de la comuna: desde el Parque Los Jubilados en Pedregal, pasando por Comfama Pedregal y la Unidad Deportiva junto al Parque Biblioteca, hasta el Parque Picacho en la parte alta.', null, 'recreacion', 1.8, 70, 'Moderado', 'parques y escenarios', 'Recreación', false, 'https://lh3.googleusercontent.com/aida-public/AB6AXuCjpUgBaQyypwNnwLItZlYCkolxBIVHxs4jyyOeNPmJ7IFTeTGqMCZjFylc55YtlKr4Pvxkwmz_oUWcBxJQD0ljqmKBfb7fQsZ168WMHQggiyMMhSNEpTIC9-spMEzkr5bPBD-xuo-kWHqT5bHEEHU6bTDmyDE72IwMFkRx3Rkx7exZQ1Cuykzjxl7V259kzPB0rMEA9GoS8Pu8X4wEQ-ihYMKCduHDhZn92id5naqaLxVhOaA8F6ah', 'Imagen ilustrativa de un parque de barrio', true, 'Equipo Ruta Doce de Octubre', 'Contenido basado en fuentes públicas', '{"icon":"sports_soccer","label":"Escenarios deportivos"}'::jsonb, '2024-04-10T00:00:00.000Z') on conflict (id) do update set caracteristica = excluded.caracteristica;
