insert into recorridos (id, titulo, descripcion_corta, descripcion, cita, categoria, distancia_km, duracion_min, dificultad, sustantivo_paradas, etiqueta, destacado, portada, portada_alt, tiene_audioguia, curador, rol_curador, caracteristica, creado_en) values ('sabores-del-doce', 'Sabores del Doce: Fogones y Panaderías del Barrio', 'Restaurantes y panaderías de Pedregal y Doce de Octubre para probar comida típica antioqueña en el barrio.', 'Ruta gastronómica por negocios del barrio sobre la Carrera 74 y alrededor de la Carrera 80: almuerzos, chicharrón, panadería y parrilla. Los horarios cambian según el negocio; conviene confirmarlos antes de ir.', null, 'gastronomia', 2.6, 90, 'Fácil', 'paradas gastronómicas', 'Gastronomía', false, 'https://lh3.googleusercontent.com/aida-public/AB6AXuAQyj8msyb0igM94uiHMyFDPRgAbMOEzfPqPOMS1WBtr73PjlSYp14E-dTI9BVJrUviTpb4rPPkNDhMUNB7Q8LYA9qBiRXV9FHcOji_klUG1UP_87Rbjl3OJrtvJfW7NN-EJrQvhAiSZhTVMWXXSAaov_1GKiSt-oBjIxIWs3WsA2ZCMwYcNNaxOCPH0KySR5d1RGXEiAvPXU2VutUe91e33oyTYY5AEtKJrpeJgvmqBEe3v_En-BCi', 'Imagen ilustrativa de comida típica antioqueña', true, 'Equipo Ruta Doce de Octubre', 'Contenido basado en fuentes públicas', '{"icon":"restaurant","label":"Negocios del barrio"}'::jsonb, '2024-05-02T00:00:00.000Z') on conflict (id) do update set caracteristica = excluded.caracteristica;
