insert into recorridos (id, titulo, descripcion_corta, descripcion, cita, categoria, distancia_km, duracion_min, dificultad, sustantivo_paradas, etiqueta, destacado, portada, portada_alt, tiene_audioguia, curador, rol_curador, caracteristica, creado_en) values ('balcones-del-picacho', 'Balcones del Picacho: Metrocable y Cerro Tutelar', 'Sube en la Línea P del Metrocable hasta El Progreso y continúa a pie hasta el Cristo y el mirador del Cerro El Picacho.', 'El Cerro El Picacho es uno de los siete cerros tutelares de Medellín y está en la Comuna 6. El recorrido empieza en la estación Doce de Octubre, sigue a la estación El Progreso y sube por el barrio hasta el Cristo y el mirador, con vista sobre todo el Valle de Aburrá. Tiene pendientes fuertes y escaleras: lleva agua y calzado cómodo.', null, 'miradores', 2.3, 150, 'Exigente', 'paradas', 'Naturaleza & vista', false, 'https://lh3.googleusercontent.com/aida-public/AB6AXuDm8juEbgGtiLRulubKxDe_5BCaA2LGGjxhdA7VKk59ukytdpZ4O8wufY1ADTpUSQgVwl88kE7yd3lk_YWKc_0hKg53RnRtNcXRcS21nxQSkk-Nlp6JKtzMpL2SyilOqyAo_ddFyBPw24cpfhLJOTl4jABaqZsaDBohZVfBVsxxnB30Mg9135MHGEJwU5tV1GsKoDY4rl7mKT0U6x_R5dE_1xkheiXyzMLwveR7q--B8UQ1nR4EULpl', 'Imagen ilustrativa de una vista panorámica desde la montaña', true, 'Equipo Ruta Doce de Octubre', 'Contenido basado en fuentes públicas', '{"icon":"cable_car","label":"Incluye Metrocable"}'::jsonb, '2024-06-15T00:00:00.000Z') on conflict (id) do update set caracteristica = excluded.caracteristica;
